//! 📷️ Public owned native boundaries consume the same independently validated PNG/zlib corpus.
use super::*;
use store::sqlite_snapshot::SnapshotEncoding;
use std::{io::Write,process::{Command,Stdio}};
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../../../🧫️fixtures/🪶️sqlite/🚦️audit/🔣️.json")).unwrap()}
fn hex(text:&str)->Vec<u8>{text.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn crc(bytes:&[u8])->u32{let mut crc=u32::MAX;for byte in bytes{crc^=u32::from(*byte);for _ in 0..8{crc=(crc>>1)^if crc&1!=0{0xedb88320}else{0};}}!crc}
fn png(input:&serde_json::Value)->Vec<u8>{let mut output=vec![137,80,78,71,13,10,26,10];for(index,chunk)in input["chunks"].as_array().unwrap().iter().enumerate(){let data=hex(chunk["dataHex"].as_str().unwrap());let tag=chunk["tag"].as_str().unwrap().as_bytes();output.extend_from_slice(&u32::try_from(data.len()).unwrap().to_be_bytes());let start=output.len();output.extend_from_slice(tag);output.extend_from_slice(&data);let checksum=crc(&output[start..])^u32::from(input["corruptCrc"].as_u64()==Some(index as u64));output.extend_from_slice(&checksum.to_be_bytes());}output}
fn carrier(bytes:&[u8],owner:&str,encoding:SnapshotEncoding)->store::io_schema::IoPayload{match encoding{SnapshotEncoding::Binary=>{let envelope=store::semio_format::SemioEnvelope::from_envelope_id(owner,store::semio_format::Component::Pack,1).unwrap();store::io_schema::IoPayload::Binary(store::semio_format::wrap_binary(&envelope,bytes))},SnapshotEncoding::Text=>{let envelope=store::semio_format::SemioEnvelope::from_envelope_id(owner,store::semio_format::Component::Dsl,1).unwrap();let text=bytes.iter().map(|byte|format!("{byte:02x}")).collect::<String>();store::io_schema::IoPayload::Text(store::semio_format::wrap_text(&envelope,&text))}}}
fn decode(bytes:&[u8],encoding:SnapshotEncoding)->Result<PngSnapshot,store::sqlite_snapshot::ValueError>{PngSnapshot::decode_sqlite_snapshot_native(&carrier(bytes,"stdio.png",encoding),&mut SqliteSnapshotControl::new(&mut |_|true,Default::default()))}
fn oracle(bytes:&[u8],script:&str)->serde_json::Value{let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));serde_json::from_slice(&output.stdout).unwrap()}
fn output(snapshot:&PngSnapshot)->Vec<u8>{match snapshot.encode_sqlite_snapshot_native(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap(){store::io_schema::IoPayload::Binary(bytes)=>store::semio_format::unwrap_binary(&bytes).unwrap().1,_=>panic!("binary PNG native output required")}}
#[test]
fn sqlite_snapshot_png_audit_backgrounds_canonicalize_source_samples_to_valid_rgba8(){
 let input=corpus();for case in input["validPng"].as_array().unwrap().iter().filter(|case|!case["background"].is_null()){for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let snapshot=decode(&png(case),encoding).unwrap();assert_eq!(snapshot.pixels,case["pixels"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap() as u8).collect::<Vec<_>>());let bytes=output(&snapshot);let measured=oracle(&bytes,"import {PNG} from 'pngjs';const bytes=Buffer.from(await Bun.stdin.arrayBuffer()),image=PNG.sync.read(bytes);let bg=null;for(let p=8;p<bytes.length;){const n=bytes.readUInt32BE(p),tag=bytes.subarray(p+4,p+8).toString('ascii'),data=bytes.subarray(p+8,p+8+n);if(tag==='bKGD'){if(n!==6)throw Error('RGBA8 background length');bg=[data.readUInt16BE(0),data.readUInt16BE(2),data.readUInt16BE(4)];}p+=n+12;}console.log(JSON.stringify({pixels:[...image.data],background:bg,depth:image.depth,colorType:image.colorType}));");assert_eq!(measured["pixels"],case["pixels"]);assert_eq!(measured["background"],case["background"]);assert_eq!(decode(&bytes,encoding).unwrap().color_type,PngColorType::Rgba);}}
}
#[test]
fn sqlite_snapshot_png_audit_text_fields_use_latin1_and_exact_itext_utf8(){
 let input=corpus();let case=input["validPng"].as_array().unwrap().iter().find(|case|case["id"]=="latin1-and-itext").unwrap();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let snapshot=decode(&png(case),encoding).unwrap();assert_eq!(snapshot.text_chunks.len(),3);for text in &snapshot.text_chunks{assert_eq!(text.keyword,input["text"]["keyword"].as_str().unwrap());}assert_eq!(snapshot.text_chunks[0].value,input["text"]["latin1Value"].as_str().unwrap());assert_eq!(snapshot.text_chunks[1].value,input["text"]["latin1Value"].as_str().unwrap());let international=&snapshot.text_chunks[2];assert_eq!(international.language_tag,input["text"]["language"].as_str().unwrap());assert_eq!(international.translated_keyword,input["text"]["translated"].as_str().unwrap());assert_eq!(international.value,input["text"]["internationalValue"].as_str().unwrap());let bytes=output(&snapshot);let measured=oracle(&bytes,"import {PNG} from 'pngjs';import {inflateSync} from 'node:zlib';const bytes=Buffer.from(await Bun.stdin.arrayBuffer());PNG.sync.read(bytes);let texts=[];for(let p=8;p<bytes.length;){const n=bytes.readUInt32BE(p),tag=bytes.subarray(p+4,p+8).toString('ascii'),data=bytes.subarray(p+8,p+8+n),z=data.indexOf(0);if(tag==='tEXt')texts.push([data.subarray(0,z).toString('latin1'),data.subarray(z+1).toString('latin1')]);if(tag==='zTXt'){if(data[z+1]!==0)throw Error('text method');texts.push([data.subarray(0,z).toString('latin1'),inflateSync(data.subarray(z+2)).toString('latin1')]);}if(tag==='iTXt'){if(data[z+1]>1||data[z+2]!==0)throw Error('iTXt flags');let l=data.indexOf(0,z+3),t=data.indexOf(0,l+1);const payload=data[z+1]?inflateSync(data.subarray(t+1)):data.subarray(t+1);texts.push([data.subarray(0,z).toString('latin1'),new TextDecoder('utf-8',{fatal:true}).decode(payload),data.subarray(z+3,l).toString('ascii'),new TextDecoder('utf-8',{fatal:true}).decode(data.subarray(l+1,t))]);}p+=n+12;}console.log(JSON.stringify(texts));");assert_eq!(measured[0][1],input["text"]["latin1Value"]);assert_eq!(measured[1][1],input["text"]["latin1Value"]);assert_eq!(measured[2][1],input["text"]["internationalValue"]);let mut nonrepresentable=snapshot.clone();nonrepresentable.text_chunks[0].value="世界".into();assert!(nonrepresentable.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}
}
#[test]
fn sqlite_snapshot_png_audit_crc_chunk_order_reserved_fields_and_text_flags_refuse(){let input=corpus();for case in input["invalidPng"].as_array().unwrap(){for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert!(decode(&png(case),encoding).is_err(),"PNG owner admitted {}",case["id"]);}}let case=input["validPng"].as_array().unwrap().iter().find(|case|case["id"]=="latin1-and-itext").unwrap();let mut snapshot=decode(&png(case),SnapshotEncoding::Binary).unwrap();snapshot.chunk_order=vec![PngChunkMarker::Ihdr,PngChunkMarker::Iend,PngChunkMarker::Idat];for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}}
#[test]
fn sqlite_snapshot_png_audit_zlib_cinfo_and_missing_dictionary_authority_are_enforced(){
 let input=corpus();let base=input["validPng"][3]["chunks"].as_array().unwrap();for(name,accepted)in[("valid32KiBHex",true),("valid256Hex",true),("advertised256InvalidDistanceHex",false),("dictionaryStreamHex",false),("wrongDictionaryIdHex",false)]{let mut chunks=vec![base[0].clone(),serde_json::json!({"tag":"zTXt","dataHex":format!("5a0000{}",input["zlib"][name].as_str().unwrap())})];chunks.extend_from_slice(&base[base.len()-2..]);let file=png(&serde_json::json!({"chunks":chunks}));for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let result=decode(&file,encoding);assert_eq!(result.is_ok(),accepted,"PNG zlib case {name}");if accepted{let value=result.unwrap();let expected=hex(input["zlib"][if name=="valid256Hex"{"smallPayloadHex"}else{"expectedPayloadHex"}].as_str().unwrap());assert_eq!(value.text_chunks[0].value,expected.into_iter().map(char::from).collect::<String>());}}}
}
#[test]
fn sqlite_snapshot_png_audit_standalone_zlib_producer_declares_its_real_window_and_dictionary_domain(){
 use semio_s_artifact_stdio_deflate::schema::snapshot::{DeflateSnapshot,DeflateLevelHint};let input=corpus();let bytes=hex(input["zlib"]["smallPayloadHex"].as_str().unwrap());let snapshot=DeflateSnapshot{schema:"stdio.deflate".into(),compression_method:8,window_bits:7,compression_level_hint:DeflateLevelHint::Default,dict_id:None,payload:bytes.clone()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let reduced=DeflateSnapshot::decode_sqlite_snapshot_native(&carrier(&hex(input["zlib"]["valid256Hex"].as_str().unwrap()),"stdio.deflate",encoding),&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(reduced.window_bits,0);assert_eq!(reduced.payload,bytes);let file=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();let normal=DeflateSnapshot::decode_sqlite_snapshot_native(&file,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(normal.window_bits,7);assert_eq!(normal.dict_id,None);assert_eq!(normal.payload,bytes);for window in[0,6]{let mut unsupported=snapshot.clone();unsupported.window_bits=window;assert!(unsupported.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}let mut dictionary=snapshot.clone();dictionary.dict_id=Some(123456789);assert!(dictionary.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());for field in["dictionaryStreamHex","wrongDictionaryIdHex"]{let foreign=carrier(&hex(input["zlib"][field].as_str().unwrap()),"stdio.deflate",encoding);assert!(DeflateSnapshot::decode_sqlite_snapshot_native(&foreign,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}}
}
